# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from dataset import get_dataloader
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=16)

class BirdCLEFModel(nn.Module):
    def __init__(self):
        super(BirdCLEFModel, self).__init__()
        self.conv_layers = nn.Sequential(
            nn.Conv2d(1, 32, kernel_size=3, padding=1), nn.BatchNorm2d(32), nn.ReLU(),
            nn.Conv2d(32, 64, kernel_size=3, padding=1), nn.BatchNorm2d(64), nn.ReLU(),
        )
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Dropout(0.2),
            nn.Linear(64, 128), nn.ReLU(),
            nn.Linear(128, 234)
        )

    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Initialize model, loss function, and optimizer
model = BirdCLEFModel().to('cuda')
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=0.0001)

# Training loop
epochs_trained = 2
training_samples = 0
eval_samples = 0

for epoch in range(epochs_trained):
    model.train()
    running_loss = 0.0
    batch_count = 0
    
    for inputs, labels in train_loader:
        if batch_count >= 10:  # Limit to ~5000 samples (~10 batches)
            break
        
        inputs, labels = inputs.to('cuda'), labels.to('cuda')
        
        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels)
        loss.backward()
        optimizer.step()
        
        running_loss += loss.item()
        training_samples += inputs.size(0)
        batch_count += 1
        
        # Print loss per batch
        print(f"Epoch [{epoch+1}/{epochs_trained}], Batch [{batch_count}/10], Loss: {loss.item():.4f}")
        
        torch.cuda.empty_cache()  # Prevent GPU fragmentation
    
    # Validation phase
    model.eval()
    all_preds = []
    all_labels = []
    
    with torch.no_grad():
        for inputs, labels in train_loader:
            if batch_count >= 20:  # Assume next ~5000 samples for validation (~10 batches)
                break
            
            inputs, labels = inputs.to('cuda'), labels.to('cuda')
            outputs = model(inputs)
            
            all_preds.append(outputs.cpu().numpy())
            all_labels.append(labels.cpu().numpy())
            
            eval_samples += inputs.size(0)
            batch_count += 1
    
    # Compute AUC
    all_preds = np.concatenate(all_preds)
    all_labels = np.concatenate(all_labels)
    
    final_auc = roc_auc_score(all_labels, all_preds, average='weighted')
    print(f"Validation AUC: {final_auc:.4f}")

# Save metrics
metrics = {
    "final_train_loss": running_loss / batch_count,
    "final_auc": float(final_auc),
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": epochs_trained,
    "batch_size": 16,
    "training_samples": training_samples,
    "eval_samples": eval_samples
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

# Print metrics for log parsing
print("METRICS: " + json.dumps(metrics))

